50: template <typename ShouldAbort>
51: [[nodiscard]] inline EvidenceSpeedLimit evidenceAwareSpeedLimitImpl(
52:     const navigation_math::StatePVAJ& state,
53:     const navigation_planning::DynamicLimits& dynamics,
54:     const std::array<double, 4>& support_m,
55:     const double sample_traj_dt_s,
56:     ShouldAbort&& should_abort) noexcept {
57:   EvidenceSpeedLimit result;
58:   if (!state.allFinite() || !dynamics.valid() ||
59:       !std::isfinite(sample_traj_dt_s) || sample_traj_dt_s <= 0.0) {
60:     return result;
61:   }
62:   result.support_m = std::numeric_limits<double>::infinity();
63:   for (const double support : support_m) {
64:     if (!std::isfinite(support) || support <= 0.0) {
65:       result.support_m = 0.0;
66:       result.failure = EvidenceSpeedFailure::kInsufficientSupport;
67:       return result;
68:     }
69:     result.support_m = std::min(result.support_m, support);
70:   }
71: 
72:   // First certify the actual PVAJ boundary under the caller's physical
73:   // recovery model. Reducing desired cruise speed does not reduce current
74:   // measured velocity, acceleration, or jerk.
75:   const auto current_stop = evaluateStopReachability(
76:       state, dynamics, result.support_m, sample_traj_dt_s);
77:   if (!current_stop.feasible) {
78:     result.failure = stopFailureToSpeedFailure(current_stop.failure);
79:     return result;
80:   }
81: 
82:   const Eigen::Vector3d velocity = state.col(1);
83:   const Eigen::Vector3d direction = velocity.norm() > 1.0e-9
84:       ? velocity.normalized() : Eigen::Vector3d::UnitX();
85:   const double upper = dynamics.intent.requested_cruise_speed_mps;
86:   // Feasibility of this polynomial family is not assumed monotone in duration
87:   // or entry speed. Inspect a fixed descending grid instead of bisection; each
88:   // accepted value has its own concrete stop-polynomial support certificate.
89:   constexpr std::size_t kBoundedSpeedSamples = 16U;
90:   for (std::size_t sample = kBoundedSpeedSamples; sample > 0U; --sample) {
91:     bool abort = false;
92:     try {
93:       abort = static_cast<bool>(should_abort());
94:     } catch (...) {
95:       abort = true;
96:     }
97:     if (abort) {
98:       result.failure = EvidenceSpeedFailure::kBudgetExhausted;
99:       return result;
100:     }
101:     const double candidate_speed =
102:         upper * static_cast<double>(sample) /
103:         static_cast<double>(kBoundedSpeedSamples);
104:     navigation_math::StatePVAJ candidate_state;
105:     candidate_state.setZero();
106:     candidate_state.col(0) = state.col(0);
107:     candidate_state.col(1) = direction * candidate_speed;
108:     // Cruise is a future steady-state proposal. Actual non-zero boundary
109:     // derivatives were independently included in current_stop above.
110:     const auto candidate_stop = evaluateStopReachability(
111:         candidate_state, dynamics, result.support_m, sample_traj_dt_s);
112:     if (candidate_stop.feasible) {
113:       result.speed_mps = candidate_speed;
114:       result.sufficient = true;
115:       result.failure = EvidenceSpeedFailure::kNone;
116:       return result;
117:     }
118:     if (candidate_stop.failure == StopFailureReason::kOutsideRecoveryEnvelope) {
119:       result.failure = EvidenceSpeedFailure::kOutsideRecoveryEnvelope;
120:     } else if (candidate_stop.failure == StopFailureReason::kSynthesisFailed) {
121:       result.failure = EvidenceSpeedFailure::kStopSynthesisFailed;
122:     }
123:   }
124:   if (result.failure == EvidenceSpeedFailure::kInvalidInput) {
125:     result.failure = EvidenceSpeedFailure::kInsufficientSupport;
126:   }
127:   return result;
128: }
