218:       _node.get_logger(), "Cmd %i: timeout, no ack received",
219:       cmd.command);
220:   }
221: 
222:   return result;
223: }
224: 
225: void ModeExecutorBase::scheduleMode(
226:   ModeBase::ModeID mode_id,
227:   const CompletedCallback & on_completed, bool forced)
228: {
229:   px4_msgs::msg::VehicleCommand cmd{};
230:   cmd.command = px4_msgs::msg::VehicleCommand::VEHICLE_CMD_SET_NAV_STATE;
231:   cmd.param1 = mode_id;
232:   scheduleMode(mode_id, cmd, on_completed, forced);
233: }
234: 
235: void ModeExecutorBase::scheduleMode(
236:   ModeBase::ModeID mode_id, const px4_msgs::msg::VehicleCommand & cmd,
237:   const CompletedCallback & on_completed, bool forced)
238: {
239:   if (!_is_armed && !forced) {
240:     on_completed(Result::Rejected);
241:     return;
242:   }
243: 
244:   // If there's already an active mode, cancel it (it will call the callback with a failure result)
245:   _current_scheduled_mode.cancel();
246: 
247:   const Result result = sendCommandSync(
248:     cmd.command, cmd.param1, cmd.param2, cmd.param3, cmd.param4, cmd.param5, cmd.param6,
249:     cmd.param7);
250: 
251:   if (result != Result::Success) {
252:     on_completed(result);
253:     return;
254:   }
255: 
256:   // Store the callback and ensure it's called eventually. There's a number of outcomes:
257:   // - The mode finishes and publishes the completion result.
258:   // - Failsafe is entered or the user switches out. In that case the executor gets deactivated.
259:   // - The user switches into the owned mode. In that case the fmu does not deactivate the executor.
260:   _current_scheduled_mode.activate(mode_id, on_completed);
261: }

480:   _owned_mode.overrideRegistration(registration);
481:   _registration = registration;
482: }
483: 
484: ModeExecutorBase::ScheduledMode::ScheduledMode(
485:   rclcpp::Node & node,
486:   const std::string & topic_namespace_prefix)
487: {
488:   _mode_completed_sub = node.create_subscription<px4_msgs::msg::ModeCompleted>(
489:     topic_namespace_prefix + "fmu/out/mode_completed" +
490:     px4_ros2::getMessageNameVersion<px4_msgs::msg::ModeCompleted>(), rclcpp::QoS(
491:       1).best_effort(),
492:     [this, &node](px4_msgs::msg::ModeCompleted::UniquePtr msg) {
493:       if (active() && msg->nav_state == static_cast<uint8_t>(_mode_id)) {
494:         RCLCPP_DEBUG(
495:           node.get_logger(), "Got matching ModeCompleted message, result: %i",
496:           msg->result);
497:         const CompletedCallback on_completed_callback(std::move(_on_completed_callback));
498:         reset();
499:         on_completed_callback(static_cast<Result>(msg->result));                 // Call after, as it might trigger new requests
500:       }
501:     });
502: }
503: 
504: void ModeExecutorBase::ScheduledMode::activate(
505:   ModeBase::ModeID mode_id,
506:   const CompletedCallback & on_completed)
507: {
508:   assert(!active());
509:   _mode_id = mode_id;
510:   _on_completed_callback = on_completed;
511: }
512: 
513: void ModeExecutorBase::ScheduledMode::cancel()
514: {
515:   if (active()) {
516:     const CompletedCallback on_completed_callback(std::move(_on_completed_callback));
517:     reset();
518:     on_completed_callback(Result::Deactivated);             // Call after, as it might trigger new requests
519:   }
520: }

