9: Mission makeMission() {
10:   Mission m;
11:   m.id = "h1-local";
12:   m.frame = "map";
13:   m.control.acceptance_speed_mps = 0.15;
14:   m.control.acceptance_confirmation_s = 0.5;
15:   for (const auto [id, x, behavior] : {
16:            std::tuple<const char*, double, MissionWaypoint::Behavior>{"start", 0.0, MissionWaypoint::Behavior::PassThrough},
17:            {"cross", 1.0, MissionWaypoint::Behavior::PassThrough},
18:            {"end", 3.0, MissionWaypoint::Behavior::Stop}}) {
19:     MissionWaypoint w;
20:     w.id = id;
21:     w.position_enu = Eigen::Vector3d{x, 0.0, 0.0};
22:     w.acceptance_radius_m = 0.1;
23:     w.behavior = behavior;
24:     m.waypoints.push_back(w);
25:   }
26:   return m;
27: }
