29: MissionControllerEvent startAtCrossing(MissionController& c) {
30:   c.activate(1.0);
31:   const auto first_goal = c.update(
32:       1.0, Eigen::Vector3d{0.0, 0.0, 0.0}, true,
33:       Eigen::Vector3d{0.0, 0.0, 0.0});
34:   assert(first_goal.type == MissionControllerEvent::Type::PublishGoal);
35:   assert(!first_goal.waypoint_accepted && c.activeRequestId() == 1U);
36:   c.onNativeTrajectoryReady();
37:   const auto accepted_start = c.update(
38:       1.005, Eigen::Vector3d{0.0, 0.0, 0.0}, true,
39:       Eigen::Vector3d{0.0, 0.0, 0.0});
40:   assert(accepted_start.type == MissionControllerEvent::Type::PublishGoal);
41:   assert(accepted_start.waypoint_accepted && accepted_start.accepted_waypoint_index == 0U);
42:   assert(c.activeWaypointIndex() == 1U);
43:   c.onNativeTrajectoryReady();
44:   const auto approach = c.update(
45:       1.01, Eigen::Vector3d{0.5, 0.0, 0.0}, true,
46:       Eigen::Vector3d{2.0, 0.0, 0.0});
47:   assert(approach.type == MissionControllerEvent::Type::None);
48:   return accepted_start;
49: }
50: 
51: CertifiedContinuation witness(const MissionController& c, std::uint64_t request_delta=0) {
52:   return CertifiedContinuation{"h1-local", 1U,
53:       c.activeRequestId() + request_delta, 10'620'000'000ULL};
54: }
55: 
56: void positiveControl() {
57:   MissionController c(makeMission());
58:   startAtCrossing(c);
59:   const auto accepted = c.update(
60:       1.06, Eigen::Vector3d{1.5, 0.0, 0.0}, true,
61:       Eigen::Vector3d{2.0, 0.0, 0.0}, witness(c));
62:   assert(accepted.type == MissionControllerEvent::Type::PublishGoal);
63:   assert(accepted.waypoint_accepted && accepted.accepted_waypoint_index == 1U);
64:   assert(c.activeWaypointIndex() == 2U);
65: }
66: 
67: void noWitnessThenLateWitness() {
68:   MissionController c(makeMission());
69:   startAtCrossing(c);
70:   const auto missed = c.update(
71:       1.06, Eigen::Vector3d{1.5, 0.0, 0.0}, true,
72:       Eigen::Vector3d{2.0, 0.0, 0.0});
73:   assert(missed.type == MissionControllerEvent::Type::None);
74:   const auto late = c.update(
75:       1.07, Eigen::Vector3d{1.5, 0.0, 0.0}, true,
76:       Eigen::Vector3d{2.0, 0.0, 0.0}, witness(c));
77:   assert(late.type == MissionControllerEvent::Type::None);
78:   assert(c.activeWaypointIndex() == 1U);
79: }
