85:       1.06, Eigen::Vector3d{1.5, 0.0, 0.0}, true,
86:       Eigen::Vector3d{2.0, 0.0, 0.0}, witness(c, 1U));
87:   assert(rejected.type == MissionControllerEvent::Type::None);
88:   assert(c.activeWaypointIndex() == 1U);
89: }
