8: int main() {
9:   using navigation_math::StatePVAJ;
10:   using navigation_planning_backend::evidenceAwareSpeedLimit;
11:   using navigation_planning_backend::evaluateStopReachability;
12: 
13:   const std::vector<double> supports{0.401, 0.45, 0.6, 1.0, 2.0, 5.0};
14:   const std::vector<double> requested_speeds{1.0, 3.0, 5.0, 8.0};
15:   std::size_t grid_rejects_with_swept_witness = 0U;
16:   std::size_t checked = 0U;
17: 
18:   for (const double support : supports) {
19:     for (const double requested : requested_speeds) {
20:       navigation_planning::DynamicLimits limits;
21:       limits.vehicle.maximum_velocity_mps = 12.0;
22:       limits.vehicle.maximum_acceleration_mps2 = 12.0;
23:       limits.vehicle.maximum_jerk_mps3 = 30.0;
24:       limits.intent.requested_cruise_speed_mps = requested;
25:       const StatePVAJ measured = StatePVAJ::Zero();
26:       const auto grid = evidenceAwareSpeedLimit(
27:           measured, limits, {support, support, support, support}, 0.05,
28:           [] { return false; });
29: 
30:       bool swept_witness = false;
31:       double first_witness = 0.0;
32:       // Independent speed enumeration over the same production stop
33:       // certificate; this checks the governor's sampled speed choices, not
34:       // collision/world validity or continuous mathematical completeness.
35:       for (int step = 1; step <= static_cast<int>(std::ceil(requested * 1000.0)); ++step) {
36:         const double speed = static_cast<double>(step) / 1000.0;
37:         if (speed > requested) break;
38:         StatePVAJ candidate = StatePVAJ::Zero();
39:         candidate.col(1).x() = speed;
40:         const auto stop = evaluateStopReachability(candidate, limits, support, 0.05);
41:         if (stop.feasible) {
42:           swept_witness = true;
43:           first_witness = speed;
44:           break;
45:         }
46:       }
47:       ++checked;
48:       if (!grid.sufficient && swept_witness) ++grid_rejects_with_swept_witness;
49:       std::cout << "support_m=" << support << " requested_mps=" << requested
50:                 << " governor_sufficient=" << grid.sufficient
51:                 << " governor_speed_mps=" << grid.speed_mps
52:                 << " fine_sweep_feasible=" << swept_witness
53:                 << " first_fine_speed_mps=" << first_witness << '\n';
54:     }
55:   }
56: 
57:   // Positive control and a lower support boundary control.
58:   navigation_planning::DynamicLimits control_limits;
59:   control_limits.vehicle.maximum_velocity_mps = 12.0;
60:   control_limits.vehicle.maximum_acceleration_mps2 = 12.0;
61:   control_limits.vehicle.maximum_jerk_mps3 = 30.0;
62:   control_limits.intent.requested_cruise_speed_mps = 5.0;
63:   const StatePVAJ measured = StatePVAJ::Zero();
64:   const auto positive = evidenceAwareSpeedLimit(
65:       measured, control_limits, {5.0, 5.0, 5.0, 5.0}, 0.05,
66:       [] { return false; });
67:   const auto missing = evidenceAwareSpeedLimit(
68:       measured, control_limits, {0.0, 5.0, 5.0, 5.0}, 0.05,
69:       [] { return false; });
70:   std::cout << "positive_control=" << positive.sufficient
71:             << " missing_support_control=" << missing.sufficient << '\n';
72:   std::cout << "checked=" << checked
73:             << " grid_rejects_with_fine_sweep_witness="
74:             << grid_rejects_with_swept_witness << '\n';
75:   return positive.sufficient && !missing.sufficient ? 0 : 1;
76: }
